// Sceglie UN video a ogni giro (Marco, 30/10/2026: «fai il lavoro completo»).
// Già sul canale = nella memoria del flusso oppure in contenuti/youtube.json (lì ci sono anche quelli pubblicati da Chrome).
// Ordine: prima le skill; poi i più vecchi prima; a parità di ora il video lungo prima del suo Short (così lo Short rimanda al lungo).
// La memoria resta fra un giro e l'altro solo quando il flusso è ATTIVO (le prove a mano non se la ricordano).
const memoria = $getWorkflowStaticData('global');
memoria.fatti = memoria.fatti || [];
memoria.ids = memoria.ids || {};
// Quota YouTube (tabella ufficiale, controllata il 30/10/2026): i caricamenti hanno un conto a parte, 100 al giorno a 1 unità
// l'uno; le altre chiamate stanno nelle 10.000 unità al giorno: sottotitoli 400 + lingua 51 + controllo del canale 1 = 452
// a video, quindi ~22 video al giorno. Tetto a 15: margine per il limite di caricamenti del canale (si azzera a mezzanotte del Pacifico).
const TETTO = 15;
const giorno = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
if (memoria.giorno !== giorno) { memoria.giorno = giorno; memoria.oggi = 0; }
// 30/10/2026: il 30/10 i video li caricava anche il compito di Chrome sul PC: 3 copie di n8n sono state cancellate (Marco)
// e restano quelle di Chrome. Qui la memoria prende gli id giusti, una volta sola. Da qui in poi carica solo n8n.
const GIUSTI = { 'video-notizia-chrome-adds-gmail-sourced-autofill-powered-by-gemini-ai': 'NT-pCaERZbk', 'video-breve-chrome-adds-gmail-sourced-autofill-powered-by-gemini-ai': 'O7KEomzUnL0', 'video-notizia-google-expands-gemini-and-search-with-connected-apps-pla': 'g0Rpj7w9HOU' };
if (!memoria.doppioni30) { for (const [t, id] of Object.entries(GIUSTI)) { memoria.ids[t] = id; if (!memoria.fatti.includes(t)) memoria.fatti.push(t); } memoria.doppioni30 = true; }
if (memoria.pieno === giorno || (memoria.oggi || 0) >= TETTO) return [];
const canale = $('Leggi i video già sul canale').first().json || {};
const gia = (tag) => memoria.fatti.includes(tag) || !!memoria.ids[tag] || !!canale[tag.slice(6)];
const pronti = [];
for (const it of $('Leggi i video pronti su GitHub').all()) {
  const r = it.json;
  const tag = String(r.tag_name || '');
  if (!tag.startsWith('video-') || tag.endsWith('-it') || gia(tag)) continue;
  // solo in inglese (Marco, 22/10/2026) e solo i video nati dopo quelli pubblicati a mano fino al 25/10/2026
  if (String(r.created_at) < '2026-10-25T00:00:00Z') continue;
  const file = (fine) => (r.assets || []).find((a) => a.name.endsWith(fine));
  if (!file('.mp4') || !file('.json')) continue;
  pronti.push({
    tag, nome: tag.slice(6), creato: r.created_at,
    breve: /^video-(breve|nuovo|settimana)-/.test(tag) ? 1 : 0,
    mp4: file('.mp4').browser_download_url, info: file('.json').browser_download_url,
    srt: file('.srt') ? file('.srt').browser_download_url : '',
  });
}
if (!pronti.length) return [];
// 30/10/2026 (Marco): prima le skill, poi tutto il resto. Le skill escono come release «video-skill-<nome>» (lungo)
// e «video-breve-skill-<nome>» (Short collegato): dentro ogni gruppo i più vecchi prima, il lungo prima del suo Short.
const prima = (p) => (/^video-(breve-)?skill-/.test(p.tag) ? 0 : 1);
pronti.sort((a, b) => prima(a) - prima(b) || a.creato.localeCompare(b.creato) || a.breve - b.breve);
return [{ json: { ...pronti[0], inCoda: pronti.length, oggi: memoria.oggi || 0 } }];

// 23/10/2026: n8n aveva caricato 6 video sul canale personale «Marco D'Elia», perché il collegamento
// Google era stato fatto prima che esistesse FreeLLMArena. YouTube carica sempre sul canale del collegamento:
// se non è FreeLLMArena il flusso si ferma con un errore e non carica niente.
// 30/10/2026: il controllo si fa solo quando c'è un video da caricare (1 unità di quota in meno a ogni giro vuoto).
const GIUSTO = 'UCaDO6FcvstiPM83lh5eH7_w';
const canale = ($input.first().json.items || [])[0] || {};
if (canale.id !== GIUSTO) throw new Error(`Canale sbagliato: il collegamento YouTube è su «${canale.snippet?.title || canale.id || 'nessun canale'}», non su FreeLLMArena. Ricollega la credenziale scegliendo FreeLLMArena.`);
return [{ json: { ...$('Scegli il video da caricare').first().json, canale: canale.snippet.title } }];

// Lo Short rimanda al suo video lungo (Marco, 23/10/2026) con «Full video: https://youtu.be/<id>», come nella pubblicazione
// da Chrome. L'id del lungo viene dalla memoria del flusso o da contenuti/youtube.json; se il lungo non è ancora sul canale,
// lo Short esce con la descrizione della release (l'ordine dei caricamenti mette il lungo prima, quindi è un caso raro).
const scelto = $('Solo sul canale FreeLLMArena').first().json;
const info = $json;
const memoria = $getWorkflowStaticData('global');
const canale = $('Leggi i video già sul canale').first().json || {};
let descrizione = String(info.descrizione || '').trim();
let collegato = '';
if (info.lungo) {
  const id = (memoria.ids || {})[info.lungo] || canale[String(info.lungo).replace(/^video-/, '')];
  if (id) {
    collegato = 'https://youtu.be/' + id;
    const riga = 'Full video: ' + collegato;
    if (/^Full video:.*$/m.test(descrizione)) descrizione = descrizione.replace(/^Full video:.*$/m, riga);
    else if (/^Full story:/m.test(descrizione)) descrizione = descrizione.replace(/^Full story:/m, riga + '\nFull story:');
    else descrizione += '\n' + riga;
  }
}
// limiti di YouTube: titolo 100 caratteri, descrizione 5.000, niente < >
const pulito = (s) => String(s || '').replace(/[<>]/g, '');
return [{ json: {
  ...scelto,
  titolo: pulito(info.titolo).slice(0, 100),
  descrizione: pulito(descrizione).slice(0, 5000),
  parole: (info.tag || []).join(','), // tag di YouTube (il campo «tag» resta quello della release)
  lingua: info.lingua || 'en',
  lungo: info.lungo || '',
  collegato,
} }];

// Segna il video come caricato (così non si ricarica), tiene il suo id per lo Short collegato e conta i caricamenti del giorno.
const memoria = $getWorkflowStaticData('global');
const v = $('Prepara la descrizione').first().json;
const id = $json.uploadId || $json.id;
if (!id) throw new Error('YouTube non ha restituito l\'id del video: ' + JSON.stringify($json).slice(0, 300));
memoria.fatti = [...(memoria.fatti || []).filter((t) => t !== v.tag), v.tag].slice(-300);
memoria.ids = memoria.ids || {};
memoria.ids[v.tag] = id;
const chiavi = Object.keys(memoria.ids);
for (const k of chiavi.slice(0, Math.max(0, chiavi.length - 300))) delete memoria.ids[k];
memoria.oggi = (memoria.oggi || 0) + 1;
return [{ json: {
  tag: v.tag, nome: v.nome, id,
  link: v.breve ? 'https://youtube.com/shorts/' + id : 'https://youtu.be/' + id,
  collegato: v.collegato, srt: v.srt, lingua: v.lingua,
} }];

// Se YouTube dice che la quota del giorno è finita, il flusso si ferma fino alla mezzanotte del Pacifico
// (niente errori a ogni mezz'ora). Ogni altro errore resta un errore, così si vede nelle esecuzioni.
const testo = JSON.stringify($json);
// anche il limite di caricamenti del canale («uploadLimitExceeded»): ci si ferma fino al giorno dopo
if (/quota|uploadLimitExceeded|exceeded the number of videos/i.test(testo)) {
  const memoria = $getWorkflowStaticData('global');
  memoria.pieno = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
  return [{ json: { fermo: 'Quota o limite di caricamenti YouTube finiti per oggi: si riprende dopo la mezzanotte del Pacifico', video: $('Prepara la descrizione').first().json.tag } }];
}
throw new Error('Caricamento su YouTube non riuscito: ' + testo.slice(0, 500));

// Corpo «multipart/related» per captions.insert: prima i dati della traccia, poi il file .srt (la voce esatta del video:
// YouTube li traduce nelle altre lingue).
const v = $('Segna come caricato').first().json;
const testo = String($json.testo || '').trim();
if (!v.srt || !testo || $json.error) return [];
const confine = 'freellmarena' + Date.now();
const dati = { snippet: { videoId: v.id, language: v.lingua || 'en', name: '', isDraft: false } };
const corpo = '--' + confine + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + JSON.stringify(dati) + '\r\n'
  + '--' + confine + '\r\nContent-Type: application/octet-stream\r\n\r\n' + testo + '\r\n'
  + '--' + confine + '--';
return [{ json: { corpo, tipo: 'multipart/related; boundary=' + confine } }];

// Gli id vanno in contenuti/youtube.json: il blog mette il video in cima al post (script/sito/blog.mjs).
// Stesso formato di script/youtube-link.mjs: { "<nome del video>": "<id YouTube>" }, rientro di 1 spazio.
// Scrive TUTTI gli id caricati dal flusso che mancano nel file: se un salvataggio non è riuscito, lo recupera il giro dopo.
const memoria = $getWorkflowStaticData('global');
const v = $('Segna come caricato').first().json;
const f = $json;
if (!f.content || !f.sha) return [];
const mappa = JSON.parse(Buffer.from(f.content, 'base64').toString('utf8'));
const nuovi = [];
for (const [tag, id] of Object.entries({ ...(memoria.ids || {}), [v.tag]: v.id })) {
  const nome = tag.replace(/^video-/, '');
  if (mappa[nome] !== id) { mappa[nome] = id; nuovi.push(nome); }
}
if (!nuovi.length) return [];
const testo = JSON.stringify(mappa, null, 1) + '\n';
return [{ json: { message: 'YouTube: ' + nuovi.join(', ').slice(0, 200), sha: f.sha, content: Buffer.from(testo, 'utf8').toString('base64'), nuovi } }];

// «Lingua del video» in YouTube Studio: senza, Studio non mostra i sottotitoli e YouTube non traduce né doppia il video. Si riscrive lo snippet com'è, con la lingua in più (50 unità di quota).
const v = $('Segna come caricato').first().json;
const video = ($json.items || [])[0];
if (!video) return [];
const s = video.snippet;
const lingua = v.lingua || 'en';
// 30/10/2026: si riscrive SEMPRE. L'API risponde già «en» dopo il caricamento, ma Studio la considera impostata (e parte
// con doppiaggio e traduzioni automatiche) solo dopo questo aggiornamento: provato sul video HeAxSIimpiE.
return [{ json: { id: video.id, snippet: { title: s.title, description: s.description, tags: s.tags || [], categoryId: s.categoryId, defaultLanguage: lingua, defaultAudioLanguage: lingua } } }];
